// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        Reverter reverter = new Reverter();
        address reverterAddr = address(reverter);

        vm.deal(reverterAddr, depositAmount);
        vm.prank(reverterAddr);
        (bool depSuccess, ) = address(c).call{value: depositAmount}("");
        require(depSuccess, "deposit failed");

        uint256 balanceBefore = c.balances(reverterAddr);
        require(balanceBefore >= withdrawAmount, "invariant: balance must cover withdrawAmount");

        vm.prank(reverterAddr);
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        uint256 balanceAfter = c.balances(reverterAddr);

        assertTrue(balanceAfter == balanceBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: forced failure");
    }
}
